func uploadWares(c *fiber.Ctx) error {
	var wares Wares
	if err := c.BodyParser(&wares); err != nil {
		return c.Status(http.StatusBadRequest).JSON(fiber.Map{"error": "Invalid input"})
	}

	// Assuming the merchant's email is stored in the context after login
	merchantEmail := c.Cookies("AUTH_COOKIE") // Retrieve the merchant's email from the cookie

	rows := strings.Split(wares.Csv, "\n")
	for _, row := range rows {
