	if _, err := uuid.Parse(entryId); err != nil {
		return c.Status(http.StatusBadRequest).SendString("Invalid entry ID")
	}

	row := db.QueryRow("SELECT id, title, content, lastModifiedBy, lastModifiedAt FROM entries WHERE id = ?", entryId)

