		panic(err)
	}

	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS wares (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		name TEXT NOT NULL,
		description TEXT NOT NULL,
		price REAL NOT NULL,
		merchant_id INTEGER,
		FOREIGN KEY(merchant_id) REFERENCES merchants(id)
	);`)
	if err != nil {
		panic(err)
	}
}

func isValidEmail(email string) bool {
