	maxPrice := c.Query("maxPrice")

	query := "SELECT w.name, w.description, w.price, m.email FROM wares w JOIN merchants m ON w.merchant_id = m.id"
	var args []interface{}

	if minPrice != "" {
		query += " WHERE w.price >= ?"
		args = append(args, minPrice)
