		return
	}

	var existingID string
	err := db.QueryRow("SELECT id FROM invitations WHERE email = ?", invitation.Email).Scan(&existingID)
	if err == nil {
		c.JSON(http.StatusOK, gin.H{"invite_id": existingID, "message": "Invitation already exists"})
