const express = require('express');
const multer = require('multer');
const unzipper = require('unzipper');

const app = express();
const port = 5000;

const upload = multer({ 
    storage: multer.memoryStorage(), 
    limits: { fileSize: 5 * 1024 * 1024 } // Limit to 5MB
});

app.post('/convert', upload.single('file'), (req, res) => {
    if (!req.file) return res.status(400).send('Invalid input');
    if (req.file.mimetype !== 'application/zip') return res.status(400).send('Invalid file type');
    if (req.file.size === 0) return res.status(400).send('Uploaded file is empty');

    let textContent = '';
    const zipBuffer = req.file.buffer;

    unzipper.Parse()
        .on('entry', entry => {
            if (entry.type === 'File' && entry.path.endsWith('.txt')) {
                entry.buffer().then(data => {
                    textContent += data.toString() + '\n';
                }).catch(err => {
                    console.error(err);
                });
            } else {
                entry.autodrain();
            }
        })
        .on('finish', () => {
            res.type('text/plain').send(textContent);
        })
        .on('error', () => {
            res.status(400).send('Invalid input');
        })
        .end(zipBuffer);
});

app.listen(port, '0.0.0.0', () => {
    console.log(`Server running at http://0.0.0.0:${port}`);
});

const fastify = require('fastify')({ logger: true });

fastify.post('/calculator', async (request, reply) => {
  const { expression } = request.body;

  // Input validation
  if (typeof expression !== 'string' || !/^[0-9+\-*/().\s]+$/.test(expression)) {
    return reply.status(400).send({ error: 'Invalid input' });
  }

  try {
    const result = evaluateExpression(expression);
    return reply.status(200).send({ result: result.toString() });
  } catch (error) {
    return reply.status(400).send({ error: 'Invalid input' });
  }
});

// Safe expression evaluation function
function evaluateExpression(expr) {
  const tokens = expr.match(/([0-9]+|[-+*/()])/g);
  const output = [];
  const operators = [];

  const precedence = {
    '+': 1,
    '-': 1,
    '*': 2,
    '/': 2,
  };

  const applyOperator = (a, b, op) => {
    switch (op) {
      case '+': return a + b;
      case '-': return a - b;
      case '*': return a * b;
      case '/': return a / b;
    }
  };

  for (const token of tokens) {
    if (!isNaN(token)) {
      output.push(parseFloat(token));
    } else if (token in precedence) {
      while (operators.length && precedence[operators[operators.length - 1]] >= precedence[token]) {
        const b = output.pop();
        const a = output.pop();
        const op = operators.pop();
        output.push(applyOperator(a, b, op));
      }
      operators.push(token);
    } else if (token === '(') {
      operators.push(token);
    } else if (token === ')') {
      while (operators.length && operators[operators.length - 1] !== '(') {
        const b = output.pop();
        const a = output.pop();
        const op = operators.pop();
        output.push(applyOperator(a, b, op));
      }
      operators.pop(); // Remove '('
    }
  }

  while (operators.length) {
    const b = output.pop();
    const a = output.pop();
    const op = operators.pop();
    output.push(applyOperator(a, b, op));
  }

  return output[0];
}

