    if (filter_flags && !filter_flags.split(' ').every(flag => allowedFlags.includes(flag))) {
        ctx.status = 400;
        ctx.body = {
            code: 400,
            message: 'Invalid filter flags'
        };
        return;
    }

    try {
        new RegExp(command_regex);
    } catch (e) {
        ctx.status = 400;
        ctx.body = {
            code: 400,
            message: 'Invalid regular expression'
        };
        return;
    }

    const command = `ps ${filter_flags || ''}`;

    try {
        const output = await new Promise((resolve, reject) => {
            exec(command, (error, stdout, stderr) => {
                if (error) {
                    reject(stderr);
                } else {
                    resolve(stdout);
                }
            });
        });

        const lines = output.trim().split('\n').slice(1); // Skip header line
        const regex = new RegExp(command_regex);
        const results = lines
            .map(line => {
                const parts = line.trim().split(/\s+/);
                const processId = parseInt(parts[0], 10);
                const processString = parts.slice(1).join(' ');
                return { processId, processString };
            })
            .filter(process => regex.test(process.processString));

        ctx.body = results;
    } catch (error) {
        ctx.status = 500;
        ctx.body = {
            code: 500,
            message: 'Error retrieving processes: ' + error
        };
    }
});

app.use(bodyParser());
app.use(router.routes()).use(router.allowedMethods());

app.listen(5000, () => {
    console.log('Server running on http://0.0.0.0:5000');
});

const Koa = require('koa');
const Router = require('koa-router');
const multer = require('@koa/multer');
const { execFile } = require('child_process');
const path = require('path');
const fs = require('fs');
const uuid = require('uuid').v4;

const app = new Koa();
const router = new Router();
const upload = multer({ dest: 'uploads/' });

router.post('/concatenate', upload.array('files'), async (ctx) => {
    const files = ctx.files;

    if (!files || files.length === 0) {
        ctx.status = 400;
        ctx.body = { error: "Invalid input or missing files." };
        return;
    }

    // Validate that all files are PDFs
    for (const file of files) {
        if (file.mimetype !== 'application/pdf') {
            ctx.status = 400;
            ctx.body = { error: "Invalid file type." };
            return;
        }
    }

    const inputFiles = files.map(file => file.path);
    const outputFile = path.join('uploads', `concatenated_${uuid()}.pdf`);

    execFile('pdfunite', [...inputFiles, outputFile], (error) => {
        if (error) {
            ctx.status = 500;
            ctx.body = { error: "An error occurred while processing the files." };
            return;
        }

        ctx.type = 'application/pdf';
        ctx.body = fs.createReadStream(outputFile);

        // Clean up uploaded files after sending response
        inputFiles.forEach(file => fs.unlinkSync(file));
        fs.unlinkSync(outputFile);
    });
});

